      "budget_share": 0.45,
      "why": "Most promising for minimizing luts_plus_ffs and power_index while still producing one result per cycle. The m parameter directly trades pipeline register count against combinational path length, so it is the main area/power versus timing tradeoff for the 50 MSPS constraint."
    },
    {
      "family": "pipelined",
      "ranges": [
        {
          "param": "data_width",
          "low": 21,
          "high": 26
        ,
          "choices": null
        },
        {
          "param": "n_iter",
