        {
          "param": "rounding",
          "low": null,
          "high": null
        ,
          "choices": [
            "trunc",
            "round"
          ]
        }
      ],
      "budget_share": 0.3,
      "why": "Fully registered one-result-per-cycle baseline. It has the shortest per-stage path and therefore the strongest throughput margin, but likely higher area and power. It is needed to establish the feasible region and the high-timing-margin end of the Pareto front."
    },
    {
      "family": "unrolled_k",
      "ranges": [
        {
          "param": "data_width",
